  AXStatics2 m ->
  stk asegs m lo (bv_unsigned sp) -> lo + 208 + AFS_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
  as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  evt asegs (aor_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF AT ioc allocb lo shi m)
